/**
 * Test flow for lookUpRecord action
 * Demonstrates looking up a single record
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const testLookUpRecord = Flow(
    {
        $id: Now.ID['test_look_up_record_flow'],
        name: 'Test Look Up Record',
        description: 'Tests the lookUpRecord core action',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_look_up_record_trigger'] },
        {
            table: 'incident',
            condition: 'active=true',
            run_flow_in: 'background',
        }
    ),
    (_params) => {
        const result = wfa.action(
            action.core.lookUpRecord,
            { $id: Now.ID['test_look_up_record_action'] },
            {
                table: 'sys_user',
                conditions: 'active=true^user_name=admin',
            }
        )

        wfa.action(
            action.core.log,
            { $id: Now.ID['test_look_up_record_log'] },
            {
                log_level: 'info',
                log_message: `lookUpRecord outputs: Record=${wfa.dataPill(result.Record, 'reference')}, Table=${wfa.dataPill(result.Table, 'string')}, status=${wfa.dataPill(result.status, 'string')}, error_message=${wfa.dataPill(result.error_message, 'string')}`,
            }
        )
    }
)
